// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Checkbox as CheckboxPrimitive } from "@/lib/primitives";
import { useInk, useMergedRef } from "@/lib/ink/vue";
import { checkboxRecipe } from "@/lib/ink/recipes/checkbox-ink";
import { REVEAL_DASH, REVEAL_WHEN_CHECKED, REVEAL_WHEN_INDETERMINATE, markTouched } from "@/lib/ink/recipes/draw-on-ink";
import { cn } from "@/lib/utils";
const Checkbox = defineUi<UI.ComponentProps<typeof CheckboxPrimitive.Root> & {
  seed?: string | number;
}>("Checkbox", ["class", "seed", "disabled", "onClickCapture"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const seed = computed(() => _props["seed"]);
  const disabled = computed(() => _props["disabled"]);
  const ref = computed(() => _props["ref"]);
  const onClickCapture = computed(() => _props["onClickCapture"]);
  const props = computed(() => omitProps(_props, ["class", "seed", "disabled", "ref", "onClickCapture"]));
  const invalid = computed(() => props.value["aria-invalid"] === true || props.value["aria-invalid"] === "true");
  const forced = computed(() => "data-focus-visible" in props.value);
  const {
    hostRef,
    hostProps,
    node
  } = useInk(() => ({
    recipe: checkboxRecipe,
    params: {
      disabled: !!disabled.value,
      invalid: invalid.value
    },
    kind: "checkbox" as const,
    seed: seed.value,
    layers: forced.value ? "all" as const : undefined
  }));
  return () => {
    return <CheckboxPrimitive.Root data-slot="checkbox" ref={useMergedRef<HTMLButtonElement>(hostRef, ref.value)} {...domProps(hostProps.value)} disabled={disabled.value} onClickCapture={e => {
      markTouched(e);
      onClickCapture.value?.(e);
    }} class={cn("peer relative isolate size-4 shrink-0 after:absolute after:-inset-1.5 disabled:cursor-not-allowed", REVEAL_DASH, REVEAL_WHEN_CHECKED, REVEAL_WHEN_INDETERMINATE, "group-hover/field:[&>svg_[data-layer=hover]]:visible group-hover/field:[&>svg_[data-layer=hover]]:opacity-100", "has-[+[data-slot=label]:hover]:[&>svg_[data-layer=hover]]:visible has-[+[data-slot=label]:hover]:[&>svg_[data-layer=hover]]:opacity-100", "has-[+input+[data-slot=label]:hover]:[&>svg_[data-layer=hover]]:visible has-[+input+[data-slot=label]:hover]:[&>svg_[data-layer=hover]]:opacity-100", className.value)} {...domProps(props.value)}>
      {node.value}
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" class="pointer-events-none absolute inset-0 hidden place-content-center leading-none font-bold forced-colors:grid forced-colors:data-[state=checked]:before:content-['✓'] forced-colors:data-[state=indeterminate]:before:content-['–']" />
    </CheckboxPrimitive.Root>;
  };
});
export { Checkbox };

import { blobFill, wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { checkLines, dashedBox, box, focusRing, RULER, chain } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import { reveal, revealId } from '@/lib/ink/recipes/draw-on-ink'
import type { PenName } from '@/lib/ink/types'

export interface CheckboxParams {
  disabled?: boolean
  invalid?: boolean
}

export const checkboxRecipe = defineRecipe<CheckboxParams>({
  id: 'checkbox',
  kind: 'checkbox',
  layers: ['rest', 'hover', 'checked', 'indeterminate', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, { w, h }, { disabled, invalid }, ctx) {
    const s = Math.min(w, h)
    const r = clamp(s * 0.1, 1.5, 3)
    const body = roundRectPoly(0.5, 0.5, w - 1, h - 1, r)
    const fine = s < 18
    const calm = ctx.calm

    if (!disabled) ctx.lazy('focus', (fink) => focusRing(fink, 0, 0, w, h, { r }))
    if (ctx.lazyOnly) return

    const outline = (): void => {
      const pen: PenName = invalid ? (calm || fine ? 'red.fine' : 'red') : calm ? 'pencil.fine' : fine ? 'ink.fine' : 'ink'
      box(ink, 0, 0, w, h, {
        pen, corner: r, opts: invalid ? { width: 1.2 } : undefined,
      })
    }

    ink.layer('rest', () => {
      if (disabled) {
        wash(ink, body, 'pencil-mark', { alpha: 0.35, material: 'wash' })
        dashedBox(ink, 0, 0, w, h, { r, pen: 'pencil', opts: { color: 'pencil', width: 1.2 } })
        return
      }
      ink.poly('under', body, 'slip', 0.85)
      outline()
    })

    if (!disabled) {
      ink.layer('hover', () => {
        if (calm) {
          box(ink, 1, 1, w - 2, h - 2, { pen: invalid ? 'red.fine' : 'pencil.fine', corner: r, loose: 0.5, opts: { alpha: 0.75, simple: true } })
          return
        }
        const d = 2 + s / 24
        ink.lines([{ pts: chain([[r + d + 1, h + d], [w + d, h + d], [w + d, r + d + 1]], [0, 0], Math.max(2.5, r), ink.next('drop')), o: RULER }], 'ink.fine', { width: 1.1 })
      })
    }

    const markPen: PenName = disabled ? 'pencil' : s < 26 ? 'ink' : 'ink.brush'
    const fillColor = disabled ? 'pencil-mark' : 'marker'
    const fillAlpha = disabled ? 0.4 : 0.86
    const fill = (alpha: number) => ink.part('fill', () => blobFill(ink, body, fillColor, { alpha, mis: clamp(s * 0.08, 1, 2) }))

    const invalidMark = (): void => {
      if (!invalid || disabled) return
      box(ink, 0, 0, w, h, { pen: calm || fine ? 'red.fine' : 'red', corner: r, opts: { width: 1.3 } })
      const a = 4 + s * 0.14
      ink.lines([{ pts: [[w - 1, -a * 0.95], [w + a * 0.3, -a * 0.4], [w + a, 0.4]], o: { start: 'soft', end: 'flick', wobble: 0.3, poly: true } }], 'red.fine', { width: 1.25 })
    }

    ink.layer('checked', () => {
      fill(fillAlpha)
      invalidMark()
      reveal(ink, { id: revealId(ctx.seed, 'c'), lines: checkLines(ink.next('check'), s * 0.12, -s * 0.1, s * 1.02), pen: markPen, box: { w, h } })
    })
    ink.layer('indeterminate', () => {
      fill(fillAlpha * 0.9)
      invalidMark()
      const y = h * 0.52
      reveal(ink, {
        id: revealId(ctx.seed, 'i'),
        lines: [{ pts: [[w * 0.22, y], [w * 0.78, y]], o: RULER }],
        pen: disabled ? 'pencil' : 'ink',
        box: { w, h },
        width: s < 20 ? 1.1 : 1.35,
      })
    })
  },
})

